export const roadmap = [
  ['foundations','Programming Foundations','Build comfort with code, logic and iteration.','Beginner',100], ['complexity','Complexity Analysis','Measure how algorithms scale and make smart trade-offs.','Beginner',100], ['arrays','Arrays & Strings','Store, access and transform sequential data.','Beginner',72], ['sorting','Searching & Sorting','Find and order data with efficient techniques.','Intermediate',38], ['linked-list','Linked Lists','Connect data dynamically through references.','Intermediate',20], ['stack','Stack & Queue','Master linear structures and ordered processing.','Intermediate',0], ['hashing','Hashing','Use fast lookup for powerful solutions.','Intermediate',0], ['trees','Trees & BST','Organise information hierarchically.','Intermediate',0], ['heap','Heap & Priority Queue','Prioritise data with efficient retrieval.','Advanced',0], ['graphs','Graphs','Model networks, paths and connections.','Advanced',0], ['greedy','Greedy Algorithms','Make locally optimal choices.','Advanced',0], ['dynamic-programming','Dynamic Programming','Break complex problems into reusable decisions.','Advanced',0]
].map(([id,title,description,difficulty,progress],i)=>({id,title,description,difficulty,progress,lessons: progress===100?'8 / 8':progress?'8 / 11':'0 / 9',number:String(i+1).padStart(2,'0')}));

export const topicInfo = {
 arrays:{title:'Arrays',blurb:'Master the fundamentals of sequential data storage and manipulation.',difficulty:'Beginner',time:'2 hours',progress:65,what:'An array stores values in adjacent memory positions. Each element has an index, so you can retrieve it directly and predictably.',why:'Arrays are the building block behind lists of marks, pixels, measurements and records. Understanding them makes iteration and data processing feel natural.',examples:['Student marks','Image pixels','Sensor readings','Game inventories','Database records']},
 strings:{title:'Strings',blurb:'Work confidently with text, characters and patterns.',difficulty:'Beginner',time:'1.5 hours',progress:60,what:'A string is an ordered sequence of characters. Algorithms use strings to compare, search, parse and transform text.',why:'Text powers search, messaging, compilers and user interfaces.',examples:['Search queries','DNA sequences','Passwords','Source code','Chat messages']},
 'linked-list':{title:'Linked Lists',blurb:'Connect flexible data through nodes and pointers.',difficulty:'Intermediate',time:'2 hours',progress:50,what:'A linked list is made of nodes where each node points to the next. It grows and shrinks without moving every item.',why:'Linked lists explain references, dynamic memory and many advanced structures.',examples:['Music playlists','Browser history','Memory allocators','Undo stacks','Task queues']},
 stack:{title:'Stacks',blurb:'Use the last-in, first-out pattern.',difficulty:'Intermediate',time:'1 hour',progress:70,what:'A stack keeps the newest item on top. You push values in and pop them back out.',why:'Stacks track nested work and reversible actions.',examples:['Undo actions','Function calls','Bracket matching','Back navigation','Expression evaluation']},
 queue:{title:'Queues',blurb:'Process work in first-in, first-out order.',difficulty:'Intermediate',time:'1 hour',progress:0,what:'A queue adds items at the rear and removes them from the front.',why:'Queues keep workloads fair and ordered.',examples:['Print jobs','Support tickets','CPU scheduling','Checkout lines','Network packets']},
 trees:{title:'Trees',blurb:'Represent hierarchy and enable efficient lookup.',difficulty:'Intermediate',time:'2.5 hours',progress:30,what:'A tree connects nodes through parent-child relationships. A binary search tree places smaller and larger values on predictable sides.',why:'Trees make hierarchical data and fast searching possible.',examples:['File systems','Autocomplete','HTML DOM','Databases','Organisation charts']},
 graphs:{title:'Graphs',blurb:'Model relationships, routes and networks.',difficulty:'Advanced',time:'3 hours',progress:20,what:'A graph contains vertices and edges. It expresses connections that do not fit a simple hierarchy.',why:'Graphs let us solve route, recommendation and network problems.',examples:['Google Maps','Social networks','Web links','Flight routes','Dependencies']},
 sorting:{title:'Searching & Sorting',blurb:'Order data and find answers efficiently.',difficulty:'Intermediate',time:'2 hours',progress:38,what:'Sorting arranges values; searching locates a target. Together they are fundamental algorithmic tools.',why:'Ordered data is easier to analyse, display and search.',examples:['Rankings','Contact lists','Product catalogues','Log analysis','Scheduling']},
 'dynamic-programming':{title:'Dynamic Programming',blurb:'Turn overlapping subproblems into efficient solutions.',difficulty:'Advanced',time:'3 hours',progress:0,what:'Dynamic programming stores answers to smaller repeated subproblems instead of calculating them again.',why:'It transforms exponential brute force into practical algorithms.',examples:['Route planning','Text comparison','Resource allocation','Games','Sequence analysis']}
};
export const problems=[['Two Sum','Arrays','Easy',10,true],['Maximum Subarray','Arrays','Medium',20,false],['Rotate Array','Arrays','Medium',20,true],['Move Zeroes','Arrays','Easy',10,false],['Valid Parentheses','Stack','Easy',10,true],['Reverse Linked List','Linked Lists','Easy',10,false],['Detect Cycle','Linked Lists','Medium',20,false],['Binary Tree Traversal','Trees','Medium',20,false],['Lowest Common Ancestor','Trees','Medium',20,false],['Number of Islands','Graphs','Medium',20,false],['Climbing Stairs','Dynamic Programming','Easy',10,true],['Coin Change','Dynamic Programming','Medium',20,false]].map(([title,topic,difficulty,xp,solved],i)=>({title,topic,difficulty,xp,solved,count:Math.max(31,284-i*17)}));
export const leaders=[['Ananya Sharma',2840,142],['Riya Mehta',2610,128],['Kavya Singh',2430,119],['Prachi Jain',2180,104],['Aditi Gupta',2050,98],['Sneha Verma',1940,91],['Nandini Rao',1820,85]].map(([name,xp,solved],i)=>({name,xp,solved,level:12-i}));
